## solutions

#### recursive

```cpp
Node* addLists(Node* head1, Node* head2, int carry) {
  if (head1 == nullptr && head2 == nullptr && carry == 0) {
    return nullptr;
  }

  int val1 = head1 == nullptr ? 0 : head1->val;
  int val2 = head2 == nullptr ? 0 : head2->val;
  int sum = val1 + val2 + carry;
  int digit = sum % 10;
  Node* head = new Node(digit);
  Node* next1 = head1 == nullptr ? nullptr : head1->next;
  Node* next2 = head2 == nullptr ? nullptr : head2->next;
  int nextCarry = sum > 9 ? 1 : 0;
  head->next = addLists(next1, next2, nextCarry);
  return head;
}
```

- n = length of list 1
- m = length of list 2
- Time: O(max(n, m))
- Space: O(max(n, m))

#### iterative

```cpp

Node* addLists(Node* head1, Node* head2) {
  Node* dummyHead = new Node(0);
  Node* tail = dummyHead;
  int carry = 0;
  Node* current1 = head1;
  Node* current2 = head2;
  while (current1 != nullptr || current2 != nullptr || carry > 0) {
    int val1 = current1 == nullptr ? 0 : current1->val;
    int val2 = current2 == nullptr ? 0 : current2->val;
    int sum = val1 + val2 + carry;
    int digit = sum % 10;
    tail->next = new Node(digit);

    if (sum > 9) {
      carry = 1;
    } else {
      carry = 0;
    }

    tail = tail->next;
    if (current1 != nullptr) {
      current1 = current1->next;
    }
    if (current2 != nullptr) {
      current2 = current2->next;
    }
  }

  return dummyHead->next;
}
```

- n = length of list 1
- m = length of list 2
- Time: O(max(n, m))
- Space: O(max(n, m))
